# --------------- Predict-with-hooks utilities ---------------
# We hook each trunk block's forward to (a) capture s,z (b) optionally intervene.
# Each block returns (s,z). We wrap block.forward.

_orig_forward = [b.forward for b in blocks]
_captured = {}  # idx -> {'s_in','z_in','s_out','z_out'}


def _restore():
    for i, b in enumerate(blocks):
        b.forward = _orig_forward[i]


def make_capture_forward(idx, orig):
    def fwd(*args, **kwargs):
        # signature: forward(sequence_state, pairwise_state, mask, pairwise_mask, chunk_size, ...)
        s_in = args[0]
        z_in = args[1]
        out = orig(*args, **kwargs)
        s_out, z_out = out
        _captured[idx] = {
            "s_in": s_in.detach().float().cpu(),
            "z_in": z_in.detach().float().cpu(),
            "s_out": s_out.detach().float().cpu(),
            "z_out": z_out.detach().float().cpu(),
        }
        return out

    return fwd


@torch.no_grad()
def predict_and_capture(seq):
    _captured.clear()
    for i, b in enumerate(blocks):
        b.forward = make_capture_forward(i, _orig_forward[i])
    try:
        pdb_str, plddt = predict_structure(seq)
    finally:
        _restore()
    caps = {
        i: {k: v for k, v in _captured[i].items()} for i in sorted(_captured.keys())
    }
    return pdb_str, plddt, caps


