# ---------- Stage 2: block-freeze causal interventions ----------
# Intervention: for blocks in a chosen window, override output so that s and/or z
# are replaced by the input (no update) OR by a scrambled-sequence reference.
# We test three modes:
#   'freeze_s_early','freeze_s_late','freeze_z_early','freeze_z_late'
# early = blocks 0..K-1, late = last K blocks. K set relative to N_BLOCKS.
K_EARLY = 8


def make_freeze_forward(orig, mode):
    def fwd(*args, **kwargs):
        s_in = args[0]
        z_in = args[1]
        out = orig(*args, **kwargs)
        s_out, z_out = out
        if mode == "s":
            s_out = s_in
        elif mode == "z":
            z_out = z_in
        elif mode == "both":
            s_out = s_in
            z_out = z_in
        return (s_out, z_out)

    return fwd


@torch.no_grad()
def predict_with_freeze(seq, block_ids, mode):
