# ---------- Stage 3: seq2pair vs pair2seq pathway ablation ----------
# We attempt to zero-out the pathway inside TriangularSelfAttentionBlock. The block's
# forward typically does:
#   z = z + seq_to_pair(s)  # outer product update
#   s = s + attention(s, pair_bias(z))  # pair2seq bias
# We monkey-patch each block's forward with a version that skips one pathway.
# Since exact API varies, we implement a wrapping approach: run the original forward
# once with a hook that saves (s_before,z_before), then compute the "unpatched" update
# and mask one delta.
# Concretely: intercept forward -> call orig -> obtain s_out,z_out. Then:
#   if pathway == 'seq2pair': z_out = z_in  (undo z update); keep s update (which uses z_in)
#   if pathway == 'pair2seq': s_out = s_in  (undo s update); keep z update
# This is a clean, well-defined ablation matching the two pathways in the trunk block.


def make_pathway_forward(orig, ablate):
    def fwd(*args, **kwargs):
        s_in = args[0]
        z_in = args[1]
        out = orig(*args, **kwargs)
        s_out, z_out = out
        if ablate == "seq2pair":
            z_out = z_in  # remove seq -> pair write
        elif ablate == "pair2seq":
            s_out = s_in  # remove pair -> seq bias
        return (s_out, z_out)

    return fwd


@torch.no_grad()
def predict_with_pathway_ablation(seq, block_ids, ablate):
    try:
        for i in block_ids:
            blocks[i].forward = make_pathway_forward(_orig_forward[i], ablate)
        pdb_str, plddt = predict_structure(seq)
    finally:
        for i, b in enumerate(blocks):
            b.forward = _orig_forward[i]
    return pdb_str, plddt


