# ---------- Stage 5: causal charge edit ----------
# Choose a target sequence (Trpzip2 or Chignolin) - neutral hydrophobic hairpin.
# We insert an "artificial charge" edit at an early block by hook that adds ±alpha * direction
# to positions in the two facing strands. We test:
#   opposite (strand1: +alpha, strand2: -alpha) — should stabilize hairpin
#   same    (strand1: +alpha, strand2: +alpha) — should destabilize
#   control (no edit)
# We probe an early block index (block 2), where charge is linearly encoded.

EDIT_BLOCK = 2
alpha_vals = [0.0, 2.0, 5.0]


def make_edit_hook(edit_positions, direction, sign_per_pos):
    """direction: (d,) unit vector on cpu; sign_per_pos: dict pos->+1/-1"""

    def fwd(*args, **kwargs):
        s_in = args[0]
        z_in = args[1]
        out = _orig_forward[EDIT_BLOCK](*args, **kwargs)
        s_out, z_out = out
        # apply edit to s_out at given positions
        d = direction.to(s_out.device).to(s_out.dtype)
        for pos, sgn in sign_per_pos.items():
            if pos < s_out.shape[1]:
                s_out[:, pos, :] = s_out[:, pos, :] + sgn * d
        return (s_out, z_out)

    return fwd


@torch.no_grad()
def predict_with_charge_edit(seq, strand1, strand2, alpha, mode):
    dir_np = charge_directions.get(EDIT_BLOCK, None)
    if dir_np is None:
        raise RuntimeError("no charge direction for edit block")
    dir_norm = dir_np / (np.linalg.norm(dir_np) + 1e-8)
    direction = torch.tensor(alpha * dir_norm)
    if mode == "opposite":
        signs = {p: +1 for p in strand1}
        signs.update({p: -1 for p in strand2})
    elif mode == "same_pos":
        signs = {p: +1 for p in strand1}
        signs.update({p: +1 for p in strand2})
    elif mode == "same_neg":
        signs = {p: -1 for p in strand1}
        signs.update({p: -1 for p in strand2})
    else:
        signs = {}
    try:
        blocks[EDIT_BLOCK].forward = make_edit_hook(
            list(signs.keys()), direction, signs
        )
        pdb_str, plddt = predict_structure(seq)
    finally:
        blocks[EDIT_BLOCK].forward = _orig_forward[EDIT_BLOCK]
    return pdb_str, plddt


charge_edit_targets = [
    # (name, seq, strand1 residues (0-indexed), strand2 residues, region)
    ("Trpzip2", "SWTWENGKWTWK", [0, 1, 2, 3], [8, 9, 10, 11], (1, 12)),
    ("Chignolin", "GYDPETGTWG", [0, 1, 2, 3], [6, 7, 8, 9], (1, 10)),
    ("HP7", "KTWNPATGKWTE", [0, 1, 2, 3], [8, 9, 10, 11], (1, 12)),
]

charge_edit_summary = {}
for name, seq, s1, s2, region in charge_edit_targets:
    for alpha in alpha_vals:
