                    pdb_str, plddt = predict_structure(seq)
                else:
                    pdb_str, plddt = predict_with_charge_edit(seq, s1, s2, alpha, mode)
                ss, tool = assign_ss(pdb_str)
                ss_full = ss[: len(seq)].ljust(len(seq), "L")
                reg = ss_full[region[0] - 1 : region[1]]
                hp = is_hairpin(reg)
                # also compute cross-strand CA distance from pdb
                try:
                    from Bio.PDB import PDBParser

                    p = PDBParser(QUIET=True)
                    st = p.get_structure("x", io.StringIO(pdb_str))
                    ca = []
                    for m_ in st:
                        for chain in m_:
                            for res in chain:
                                if "CA" in res:
                                    ca.append(res["CA"].coord)
                        break
                    ca = np.array(ca)
                    pair_d = []
                    for a, b in zip(s1[::-1], s2):
                        if a < len(ca) and b < len(ca):
                            pair_d.append(float(np.linalg.norm(ca[a] - ca[b])))
                    mean_pair_d = float(np.mean(pair_d)) if pair_d else float("nan")
                except Exception:
                    mean_pair_d = float("nan")
                charge_edit_summary[key] = {
                    "hp": bool(hp),
                    "plddt": float(plddt),
                    "reg": reg,
                    "mean_cross_strand_CA": mean_pair_d,
                }
                print(
                    f"[edit] {key}: hp={hp} plddt={plddt:.2f} cross_d={mean_pair_d:.2f} reg={reg}"
